/**
 * @file    qnn_mock_model.cc
 * @date    22 Nov 2026
 * @brief   A mock QNN model library for the qnn sub-plugin tests
 * @see     http://github.com/nnstreamer/nnstreamer
 * @author  MyungJoo Ham <myungjoo.ham@samsung.com>
 * @bug     No known bugs
 *
 * It exports the two functions a model library generated by the QNN SDK
 * exports, and composes the graph described in qnn_mock.h through the
 * interface of the backend, as a generated model does.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "qnn_mock.h"

namespace
{
uint32_t graph_count = 1;
bool fail_compose = false;
Qnn_DataType_t input_type = QNN_DATATYPE_UINT_8;
bool tensor_v2 = false;
bool dynamic_flags = false;
Qnn_QuantizationEncoding_t quantization = QNN_QUANTIZATION_ENCODING_UNDEFINED;
uint32_t num_axis_scale_offsets = 0;
uint32_t input_rank = 4;
uint32_t output_rank = 4;
uint32_t num_inputs = 1;
uint32_t num_outputs = 2;
int live_graphs = 0;

/** @brief Fill a tensor of the graph. */
void
set_tensor (Qnn_Tensor_t *t, uint32_t id, const char *name, Qnn_TensorType_t type,
    Qnn_DataType_t data_type, uint32_t rank, const uint32_t *dims)
{
  memset (t, 0, sizeof (*t));
  t->version = tensor_v2 ? QNN_TENSOR_VERSION_2 : QNN_TENSOR_VERSION_1;
  t->v1.id = id;
  t->v1.name = strdup (name);
  t->v1.type = type;
  t->v1.dataType = data_type;
  t->v1.quantizeParams.encodingDefinition = QNN_DEFINITION_UNDEFINED;
  t->v1.quantizeParams.quantizationEncoding = QNN_QUANTIZATION_ENCODING_UNDEFINED;
  t->v1.rank = rank;
  t->v1.dimensions = (uint32_t *) malloc (rank * sizeof (uint32_t));
  memcpy (t->v1.dimensions, dims, rank * sizeof (uint32_t));
  t->v1.memType = QNN_TENSORMEMTYPE_RAW;

  if (tensor_v2 && dynamic_flags) {
    t->v2.isDynamicDimensions = (uint8_t *) calloc (rank, sizeof (uint8_t));
    t->v2.isDynamicDimensions[0] = 1;
  }
}

/** @brief Free what set_tensor () allocated. */
void
clear_tensor (Qnn_Tensor_t *t)
{
  free ((void *) t->v1.name);
  free (t->v1.dimensions);
  if (t->v1.quantizeParams.quantizationEncoding == QNN_QUANTIZATION_ENCODING_AXIS_SCALE_OFFSET)
    free (t->v1.quantizeParams.axisScaleOffsetEncoding.scaleOffset);
  if (t->version == QNN_TENSOR_VERSION_2)
    free (t->v2.isDynamicDimensions);
}

/** @brief Free a composed graph. */
void
free_graph_info (QnnMockGraphInfo_t *info)
{
  for (uint32_t i = 0; i < info->numInputTensors; i++)
    clear_tensor (&info->inputTensors[i]);
  for (uint32_t i = 0; i < info->numOutputTensors; i++)
    clear_tensor (&info->outputTensors[i]);
  free (info->inputTensors);
  free (info->outputTensors);
  free (info->graphName);
  free (info);
  live_graphs--;
}

/** @brief Compose one graph. */
QnnMockGraphInfo_t *
compose_graph (const QNN_INTERFACE_VER_TYPE &qnn, Qnn_ContextHandle_t context)
{
  static const uint32_t image_dims[] = { 1, 4, 4, 3 };
  static const uint32_t sum_dims[] = { 1 };
  Qnn_GraphHandle_t graph = nullptr;
  uint32_t in_dims[QNN_MOCK_MAX_RANK], out_dims[QNN_MOCK_MAX_RANK];

  /* outer dimensions of 1 in front of [1, 4, 4, 3] */
  for (uint32_t i = 0; i < input_rank; i++)
    in_dims[i] = (i + 3 < input_rank) ? 1 : image_dims[i + 4 - input_rank];
  for (uint32_t i = 0; i < output_rank; i++)
    out_dims[i] = (i + 3 < output_rank) ? 1 : image_dims[i + 4 - output_rank];

  if (!qnn.graphCreate || qnn.graphCreate (context, "qnn_mock_graph", nullptr, &graph) != QNN_SUCCESS)
    return nullptr;

  QnnMockGraphInfo_t *info = (QnnMockGraphInfo_t *) calloc (1, sizeof (*info));
  live_graphs++;
  info->graph = graph;
  info->graphName = strdup ("qnn_mock_graph");
  info->numInputTensors = num_inputs;
  info->inputTensors = (Qnn_Tensor_t *) calloc (num_inputs, sizeof (Qnn_Tensor_t));
  info->numOutputTensors = num_outputs;
  info->outputTensors = (Qnn_Tensor_t *) calloc (num_outputs, sizeof (Qnn_Tensor_t));

  set_tensor (&info->inputTensors[0], 0, "in0", QNN_TENSOR_TYPE_APP_WRITE,
      input_type, input_rank, in_dims);
  for (uint32_t i = 1; i < num_inputs; i++) {
    char name[32];

    snprintf (name, sizeof (name), "extra_in%u", i);
    set_tensor (&info->inputTensors[i], 1000 + i, name,
        QNN_TENSOR_TYPE_APP_WRITE, QNN_DATATYPE_INT_32, 1, sum_dims);
  }
  set_tensor (&info->outputTensors[0], 1, "out0", QNN_TENSOR_TYPE_APP_READ,
      QNN_DATATYPE_UINT_8, output_rank, out_dims);
  set_tensor (&info->outputTensors[1], 2, "sum", QNN_TENSOR_TYPE_APP_READ,
      QNN_DATATYPE_INT_32, 1, sum_dims);
  for (uint32_t i = 2; i < num_outputs; i++) {
    char name[32];

    snprintf (name, sizeof (name), "extra%u", i);
    set_tensor (&info->outputTensors[i], i + 1, name, QNN_TENSOR_TYPE_APP_READ,
        QNN_DATATYPE_INT_32, 1, sum_dims);
  }

  Qnn_QuantizeParams_t *q = &info->inputTensors[0].v1.quantizeParams;
  if (quantization == QNN_QUANTIZATION_ENCODING_SCALE_OFFSET) {
    q->encodingDefinition = QNN_DEFINITION_DEFINED;
    q->quantizationEncoding = QNN_QUANTIZATION_ENCODING_SCALE_OFFSET;
    q->scaleOffsetEncoding.scale = QNN_MOCK_SCALE;
    q->scaleOffsetEncoding.offset = QNN_MOCK_OFFSET;
  } else if (quantization == QNN_QUANTIZATION_ENCODING_AXIS_SCALE_OFFSET) {
    q->encodingDefinition = QNN_DEFINITION_DEFINED;
    q->quantizationEncoding = QNN_QUANTIZATION_ENCODING_AXIS_SCALE_OFFSET;
    q->axisScaleOffsetEncoding.axis = QNN_MOCK_AXIS;
    q->axisScaleOffsetEncoding.numScaleOffsets = num_axis_scale_offsets;
    q->axisScaleOffsetEncoding.scaleOffset = nullptr;
    if (num_axis_scale_offsets > 0) {
      q->axisScaleOffsetEncoding.scaleOffset = (Qnn_ScaleOffset_t *) calloc (
          num_axis_scale_offsets, sizeof (Qnn_ScaleOffset_t));
    }
    for (uint32_t i = 0; i < num_axis_scale_offsets; i++) {
      q->axisScaleOffsetEncoding.scaleOffset[i].scale = QNN_MOCK_AXIS_SCALE (i);
      q->axisScaleOffsetEncoding.scaleOffset[i].offset = QNN_MOCK_AXIS_OFFSET (i);
    }
  }

  return info;
}

} /* namespace */

extern "C" {

/**
 * @brief Compose the graphs of the model, as a model library of the QNN SDK does.
 */
int
QnnModel_composeGraphs (Qnn_BackendHandle_t backend, QNN_INTERFACE_VER_TYPE qnn,
    Qnn_ContextHandle_t context, const void **graph_configs,
    const uint32_t num_graph_configs, QnnMockGraphInfo_t ***graphs_info,
    uint32_t *num_graphs, bool debug, QnnLog_Callback_t log_callback, QnnLog_Level_t level)
{
  (void) backend;
  (void) graph_configs;
  (void) num_graph_configs;
  (void) debug;
  (void) log_callback;
  (void) level;

  if (fail_compose || !graphs_info || !num_graphs)
    return QNN_MOCK_MODEL_GRAPH_ERROR;

  QnnMockGraphInfo_t **list
      = (QnnMockGraphInfo_t **) calloc (graph_count, sizeof (QnnMockGraphInfo_t *));
  for (uint32_t i = 0; i < graph_count; i++) {
    list[i] = compose_graph (qnn, context);
    if (!list[i]) {
      for (uint32_t j = 0; j < i; j++)
        free_graph_info (list[j]);
      free (list);
      return QNN_MOCK_MODEL_GRAPH_ERROR;
    }
  }

  *graphs_info = list;
  *num_graphs = graph_count;
  return QNN_MOCK_MODEL_NO_ERROR;
}

/**
 * @brief Free the first @a num_graphs graphs and the list returned by
 *        QnnModel_composeGraphs (), as a model library of the QNN SDK does.
 */
int
QnnModel_freeGraphsInfo (QnnMockGraphInfo_t ***graphs_info, uint32_t num_graphs)
{
  if (!graphs_info || !*graphs_info)
    return QNN_MOCK_MODEL_TENSOR_ERROR;

  for (uint32_t i = 0; i < num_graphs; i++)
    free_graph_info ((*graphs_info)[i]);
  free (*graphs_info);
  *graphs_info = nullptr;
  return QNN_MOCK_MODEL_NO_ERROR;
}

/** @brief Restore the default model. */
void
qnn_mock_model_reset (void)
{
  graph_count = 1;
  fail_compose = false;
  input_type = QNN_DATATYPE_UINT_8;
  tensor_v2 = false;
  dynamic_flags = false;
  quantization = QNN_QUANTIZATION_ENCODING_UNDEFINED;
  num_axis_scale_offsets = 0;
  input_rank = 4;
  output_rank = 4;
  num_inputs = 1;
  num_outputs = 2;
}

/** @brief Make composing fail. */
void
qnn_mock_model_fail_compose (void)
{
  fail_compose = true;
}

/** @brief Set the number of graphs. */
void
qnn_mock_model_set_graph_count (uint32_t count)
{
  graph_count = count;
}

/** @brief Set the data type of in0. */
void
qnn_mock_model_set_input_type (Qnn_DataType_t type)
{
  input_type = type;
}

/** @brief Describe the tensors as version 2 tensors. */
void
qnn_mock_model_use_tensor_v2 (bool with_dynamic_flags)
{
  tensor_v2 = true;
  dynamic_flags = with_dynamic_flags;
}

/** @brief Quantize in0. */
void
qnn_mock_model_set_quantization (Qnn_QuantizationEncoding_t encoding, uint32_t num)
{
  quantization = encoding;
  num_axis_scale_offsets = num;
}

/** @brief Set the ranks of in0 and out0. */
void
qnn_mock_model_set_ranks (uint32_t in_rank, uint32_t out_rank)
{
  input_rank = (in_rank < 4)                 ? 4 :
               (in_rank > QNN_MOCK_MAX_RANK) ? QNN_MOCK_MAX_RANK :
                                               in_rank;
  output_rank = (out_rank < 4)                 ? 4 :
                (out_rank > QNN_MOCK_MAX_RANK) ? QNN_MOCK_MAX_RANK :
                                                 out_rank;
}

/** @brief Set the numbers of inputs and outputs. */
void
qnn_mock_model_set_num_tensors (uint32_t inputs, uint32_t outputs)
{
  num_inputs = (inputs < 1) ? 1 : inputs;
  num_outputs = (outputs < 2) ? 2 : outputs;
}

/** @brief The number of composed graphs not freed yet. */
int
qnn_mock_model_live_graphs (void)
{
  return live_graphs;
}

} /* extern "C" */
